import csv

def find_clashes(path):
    seen = {}
    clashes = []
    with open(path, newline="") as f:
        for row in csv.DictReader(f):
            if not row["chair"]:          # skip blank rows
                continue
            key = (row["site"], row["chair"], row["start"])
            if key in seen:
                clashes.append((key, seen[key], row["patient_id"]))
            else:
                seen[key] = row["patient_id"]
    return clashes

for key, first, second in find_clashes("next_week.csv"):
    print("CLASH", key, "patients", first, "and", second)

